style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
/* Global Dark Background with Image */
    body {
        background: black url("https://i.pinimg.com/1200x/4f/18/47/4f1847a71992f82eb5e3f599da7b1b10.jpgabove") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* General Text Settings */
    * {
        font-family: 'Press Start 2P', monospace !important; /* Pixel/Retro font */
        text-shadow: 2px 2px 5px rgba(255, 255, 255, 0.3); /* Soft glow */
    }

    /* Links */
    a {
        text-decoration: none !important;
        transition: all 0.3s ease-in-out;
    }
    
    a:hover {
        text-shadow: 0px 0px 5px rgba(255, 255, 255, 0.8);
    }

    /* Input Fields */
    input, textarea {
        background: rgba(34, 34, 34, 0.8) !important;
        border: 2px solid rgba(255, 255, 255, 0.3) !important;
        padding: 5px !important;
        border-radius: 5px;
    }

    /* Buttons */
    button {
        background: rgba(255, 0, 128, 0.8) !important;
        border: 2px solid rgba(10, 255, 10, 0.8) !important;
        text-transform: uppercase;
        box-shadow: 0px 0px 5px rgba(255, 0, 128, 0.8);
        padding: 10px 15px;
        cursor: pointer;
        transition: all 0.3s ease-in-out;
    }

    button:hover {
        background: rgba(255, 204, 0, 0.8) !important;
        box-shadow: 0px 0px 10px rgba(255, 204, 0, 0.8);
        transform: scale(1.1);
    }

    /* Borders */
    * {
        border-color: rgba(255, 0, 128, 0.5) !important;
    }

    /* Headers */
    h1, h2, h3, h4, h5, h6 {
        text-shadow: 2px 2px 5px rgba(255, 204, 0, 0.5);
    }

    /* CRT Flicker Effect */
    @keyframes crt-flicker {
        0% { opacity: 1; }
        50% { opacity: 0.98; }
        100% { opacity: 1; }
    }

    body {
        animation: crt-flicker 0.2s infinite alternate;
    }

    /* Scanline Effect */
    body::after {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: repeating-linear-gradient(
            to bottom,
            rgba(0, 0, 0, 0) 0px,
            rgba(0, 0, 0, 0.1) 2px,
            rgba(0, 0, 0, 0) 4px
        );
        pointer-events: none;
        z-index: 9999;
    }

    /* Glowing Borders for Input Fields */
    input:focus, textarea:focus {
        border-color: rgba(255, 204, 0, 1) !important;
        box-shadow: 0px 0px 10px rgba(255, 204, 0, 0.8);
    }
}
